def find_suspicious_pair(transactions, suspicious_total):
    seen = {}
    for i, amount in enumerate(transactions):
        needed = suspicious_total - amount
        if needed in seen:
            return [seen[needed], i]
        seen[amount] = i
    return None

transactions = [100, 200, 150, 300, 50]
print(find_suspicious_pair(transactions, 450))

def two_sum_advanced(nums, target):
    seen = {}
    result = []
    for i, num in enumerate(nums):
        complement = target - num
        if complement in seen:
            for prev_idx in seen[complement]:
                result.append([prev_idx, i])
        if num not in seen:
            seen[num] = []
        seen[num].append(i)
    return result

print(two_sum_advanced([1, -1, 2, 3, -1], 0))

def closest_two_sum(nums, target):
    seen = {}
    best_pair = None
    min_diff = float('inf')
    for i, num in enumerate(nums):
        complement = target - num
        if complement in seen:
            diff = i - seen[complement]
            if diff < min_diff:
                min_diff = diff
                best_pair = [seen[complement], i]
        if num not in seen:
            seen[num] = i
    return best_pair

print(closest_two_sum([4, 1, 2, 3, 5], 6))

def match_bulk_orders(order_quantities, bulk_total):
    seen = {}
    for idx, qty in enumerate(order_quantities):
        needed = bulk_total - qty
        if needed in seen:
            return [seen[needed], idx]
        seen[qty] = idx
    return None

orders = [120, 80, 200, 50, 150]
print(match_bulk_orders(orders, 200))

def modular_two_sum(nums, target, mod):
    seen = {}
    target_mod = target % mod
    for i, num in enumerate(nums):
        needed_mod = (target_mod - (num % mod)) % mod
        if needed_mod in seen:
            return [seen[needed_mod], i]
        seen[num % mod] = i
    return None

print(modular_two_sum([3, 5, 8, 2], 7, 10))
